function morphshape4(ctx,ctrans,frame,ratio,time){
	var pathData="M -6335 -6335 -550 -550 L -6335 -6335 30 30 -6255 6907 30 30 -6255 6907 -550 -550 -6335 -6335 -550 -550";
	ctx.fillStyle=tocolor(ctrans.apply([Math.round(102+ratio*(0)/65535),Math.round(153+ratio*(0)/65535),Math.round(204+ratio*(1)/65535),((Math.round(51+ratio*(0)/65535))/255)]));
	drawMorphPath(ctx,pathData,ratio,false);

	ctx.fill("evenodd");
	var pathData="M -6335 -6335 -550 -550 L -6255 6907 -550 -550 -6255 6907 30 30 -6335 -6335 30 30 -6335 -6335 -550 -550 Z";
	var scaleMode = "NORMAL";
	ctx.strokeStyle=tocolor(ctrans.apply([Math.round(0+ratio*(0)/65535),Math.round(0+ratio*(0)/65535),Math.round(0+ratio*(1)/65535),((Math.round(0+ratio*(0)/65535))/255)]));
	ctx.lineWidth=0.0+ratio*(0)/65535;
	ctx.lineCap="round";
	ctx.lineJoin="round";
	drawMorphPath(ctx,pathData,ratio,true,scaleMode);

}

